    var s1 = Math.max(s0 + 4, curSt.endS || totalTargetS);
    var prevG = curSt.startG != null
      ? +curSt.startG
      : (curIdx > 0 && steps[curIdx - 1] ? (+steps[curIdx - 1].targetG || 0) : 0);
    var tgtG = curSt.targetG != null ? +curSt.targetG : rec.hotPourG;
