        coffeeRef: coffeeId,
        sessionSig: sessionSig,
        hasUserRated: preRated,
        goldLocked: false,
        guideCollapsed: true,
        coolingCardCollapsed: true,
        mode: (opts && opts.initialMode) || 'quick', /* 'quick' | 'guided' | 'cva' */
        stars: preRated ? (+st.stars > 0 ? +st.stars : 4.25) : 0,
        makeAgain: '',
        padX: 0,
        padY: 0,
        vessel: 'preheated_ceramic',
        lidOff: false,
