  m = /(?:^|[#?&])bt1=([A-Za-z0-9\-_]{8,})/i.exec(txt);
  if (m) return 'bt1:' + m[1];
  m = /(?:^|[#?&])bp1=([A-Za-z0-9\-_]{8,})/i.exec(txt);
  if (m) return '#bp1=' + m[1];
  m = /(?:^|#)\s*(BT6:[A-Za-z0-9\-_]{8,}|bt1:[A-Za-z0-9\-_]{8,})/i.exec(txt);
